import numpy as np, itertools
def ket(bits):
    v=np.zeros(16); v[int(bits,2)]=1.0; return v
ghz=(ket('0000')+ket('1111'))/np.sqrt(2)
def rho_pq(p,q,r):
    R=p*np.outer(ghz,ghz)+q*np.outer(ket('1010'),ket('1010'))+r*np.outer(ket('1001'),ket('1001'))
    return R
def S_sub(rho, keep):
    # rho on 4 qubits; partial trace to subset keep
    t=rho.reshape([2]*8)
    rest=[i for i in range(4) if i not in keep]
    for i in sorted(rest, reverse=True):
        t=np.trace(t, axis1=i, axis2=i+ (t.ndim//2))
    n=len(keep); m=t.reshape(2**n,2**n)
    w=np.linalg.eigvalsh(m); w=w[w>1e-14]
    return float(-(w*np.log2(w)).sum())
def entvec(rho):
    return {frozenset(s): S_sub(rho,sorted(s)) for r in range(1,5) for s in itertools.combinations(range(4),r)}
def f_of(S, perm):
    # perm maps roles (A,B,C,D) -> physical qubits
    A,B,C,D=perm; g=lambda *x: S[frozenset(x)]
    return (g(A,B,D)+g(A,B,C)+g(B,C,D)-2*g(B,D)-2*g(B,C)+g(C,D)
            -g(A,D)-g(A,C)-g(A,B)+2*g(B)+g(A))
def ing(S,perm):
    A,B,C,D=perm; g=lambda *x: S[frozenset(x)]
    I2=lambda x,y: g(x)+g(y)-g(x,y)
    I2c=lambda x,y,z: g(x,z)+g(y,z)-g(x,y,z)-g(z)
    return I2c(A,B,C)+I2c(A,B,D)+I2(C,D)-I2(A,B)

S=entvec(rho_pq(0.5,0.25,0.25))
worst=max((f_of(S,p), p) for p in itertools.permutations(range(4)))
wing=min((ing(S,p), p) for p in itertools.permutations(range(4)))
print('LMRW state: max candidate LHS over 24 relabelings =', round(worst[0],6), worst[1])
print('LMRW state: min Ingleton over relabelings =', round(wing[0],6), wing[1])
# scan mixture weights
best=(-9,None)
for p in np.linspace(0.01,0.99,49):
    for q in np.linspace(0,1-p,25):
        r=1-p-q
        S=entvec(rho_pq(p,q,r))
        for pm in itertools.permutations(range(4)):
            v=f_of(S,pm)
            if v>best[0]: best=(v,(round(p,3),round(q,3),round(r,3),pm))
print('max candidate LHS over weight scan+relabelings:', round(best[0],6), best[1])
